import sys


def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    INF = float("inf")
    d = [[INF] * (n + 1) for _ in range(n + 1)]
    for i in range(1, n + 1):
        d[i][i] = 0
    idx = 1
    for _ in range(n - 1):
        a = int(data[idx])
        b = int(data[idx + 1])
        idx += 2
        d[a][b] = 1
        d[b][a] = 1
    for k in range(1, n + 1):
        for i in range(1, n + 1):
            for j in range(1, n + 1):
                if d[i][k] + d[k][j] < d[i][j]:
                    d[i][j] = d[i][k] + d[k][j]
    out = []
    leaves = 0
    for v in range(1, n + 1):
        dep = d[1][v]
        par = 0
        for u in range(1, n + 1):
            if d[v][u] == 1 and d[1][u] == dep - 1:
                par = u
        sz = 0
        for w in range(1, n + 1):
            if d[1][w] == dep + d[v][w]:
                sz += 1
        kids = 0
        for u in range(1, n + 1):
            if d[v][u] == 1 and d[1][u] == dep + 1:
                kids += 1
        if kids == 0:
            leaves += 1
        out.append(f"{par} {dep} {sz}")
    out.append(str(leaves))
    print("\n".join(out))


main()
